create table public.baseline_forecast_runs(id uuid primary key default gen_random_uuid(),run_key text not null unique,model_version text not null,feature_version text not null,cohort_policy_version text not null,information_cutoff_at timestamptz not null,started_at timestamptz not null default now(),completed_at timestamptz,status text not null check(status in('RUNNING','COMPLETED','FAILED')),forecasts_evaluated integer not null default 0,forecasts_available integer not null default 0,last_error text);
create table public.baseline_feature_snapshots(id uuid primary key default gen_random_uuid(),snapshot_key text not null unique,forecast_id uuid references public.forecasts(id),asset_id uuid not null references public.assets(id),feature_version text not null,information_cutoff_at timestamptz not null,available_at timestamptz not null,price_momentum_5m numeric,volume_multiple_5m numeric,liquidity_usd numeric,market_cap_usd numeric,data_quality numeric not null,feature_payload jsonb not null default'{}',feature_hash text not null);
create table public.baseline_cohort_members(id uuid primary key default gen_random_uuid(),forecast_id uuid not null references public.forecasts(id),source_observation_id uuid not null references public.crypto_market_observations(id),anchor_at timestamptz not null,outcome_at timestamptz not null,return_pct numeric not null,feature_distance numeric not null default 0,available_at timestamptz not null,member_hash text not null unique,unique(forecast_id,source_observation_id));
create or replace function public.prevent_baseline_forecast_mutation()returns trigger language plpgsql as $$begin raise exception'Baseline forecast history is immutable';end$$;
create trigger baseline_feature_snapshots_immutable before update or delete on public.baseline_feature_snapshots for each row execute function public.prevent_baseline_forecast_mutation();create trigger baseline_cohort_members_immutable before update or delete on public.baseline_cohort_members for each row execute function public.prevent_baseline_forecast_mutation();
alter table public.baseline_forecast_runs enable row level security;alter table public.baseline_feature_snapshots enable row level security;alter table public.baseline_cohort_members enable row level security;create policy "public read baseline runs" on public.baseline_forecast_runs for select using(true);create policy "public read baseline features" on public.baseline_feature_snapshots for select using(true);create policy "public read baseline cohorts" on public.baseline_cohort_members for select using(true);grant select on public.baseline_forecast_runs,public.baseline_feature_snapshots,public.baseline_cohort_members to anon,authenticated;grant all on public.baseline_forecast_runs,public.baseline_feature_snapshots,public.baseline_cohort_members to service_role;
alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes','market_events','paper_eligibility','paper_execution','paper_exits','paper_valuation','performance','fx','qualification','data_gap_closure','simulation','historical_replay','forecast_catalyst','expert_knowledge','baseline_forecast'));
